// tb.v: random-stimulus testbench for Resize, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg [7:0] a = 8'd0;
    reg [7:0] b = 8'd0;
    reg [7:0] s = 8'd0;
    reg [1:0] idx = 2'd0;
    reg [31:0] arr = 32'd0;
    wire [8:0] z9;
    wire carry;
    wire [3:0] t4;
    wire [2:0] tpath;
    wire [15:0] sx;
    wire [11:0] sx2;
    wire [11:0] sx3;
    wire [4:0] sx1;
    wire [3:0] hi;
    wire [12:0] cat;
    wire [3:0] rep;
    wire [7:0] elem;
    wire [3:0] elem_lo;
    wire [7:0] elem_x;
    wire bit_;
    wire [7:0] scat;
    wire [7:0] sres;
    wire [3:0] sres2;
    wire [1:0] slsl;
    wire [3:0] trunc_div;
    wire [3:0] ssl;
    wire [3:0] loc1;
    wire [11:0] loc2;
    wire [31:0] vec_out;
    wire [23:0] small_out;
    wire [7:0] small_rd;
    reg [57:0] stim [0:239];
    integer i;

    Resize dut (
        .a(a),
        .b(b),
        .s(s),
        .idx(idx),
        .arr(arr),
        .z9(z9),
        .carry(carry),
        .t4(t4),
        .tpath(tpath),
        .sx(sx),
        .sx2(sx2),
        .sx3(sx3),
        .sx1(sx1),
        .hi(hi),
        .cat(cat),
        .rep(rep),
        .elem(elem),
        .elem_lo(elem_lo),
        .elem_x(elem_x),
        .bit_(bit_),
        .scat(scat),
        .sres(sres),
        .sres2(sres2),
        .slsl(slsl),
        .trunc_div(trunc_div),
        .ssl(ssl),
        .loc1(loc1),
        .loc2(loc2),
        .vec_out(vec_out),
        .small_out(small_out),
        .small_rd(small_rd)
    );

    task do_reset;
        begin
            #1;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {a, b, s, idx, arr} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h", i, z9, carry, t4, tpath, sx, sx2, sx3, sx1, hi, cat, rep, elem, elem_lo, elem_x, bit_, scat, sres, sres2, slsl, trunc_div, ssl, loc1, loc2, vec_out, small_out, small_rd);
            #9;
        end
        $finish;
    end
endmodule
